"""Legacy v1.1.0 synthetic account compatibility and offline recovery safety."""

import json
import secrets
from types import SimpleNamespace

import pytest
from fastapi import FastAPI, HTTPException
from fastapi.testclient import TestClient

from app.api.routes.auth import router
from app.jiahui.auth import AuthStore
from app.jiahui.recovery import inspect_accounts, select_existing_data
from scripts.jiahui_desktop import data_directory

# Generated by executing the released v1.1.0 AuthStore with this test-only passphrase.
LEGACY_PASS = "legacy-test-only-passphrase"
LEGACY_ROW = (
    "LegacyAdmin",
    "95936bf925f3c8143e23cf4100949833",
    "1ecce2c5ce056304941e57ba5d3412fc1a18cf578b3cfe9889721302c2be3f6d",
    "admin",
    "audit,inventory,knowledge,orders,prices,products",
    1,
)


def legacy_store(path):
    store = AuthStore(path)
    with store._connect() as db:
        db.execute(
            "INSERT INTO users(username,salt,password_hash,role,scopes,active) VALUES(?,?,?,?,?,?)",
            LEGACY_ROW,
        )
    return store


def test_released_account_logs_into_new_version_without_password_reset(tmp_path):
    old = legacy_store(tmp_path / "old-data")
    del old
    upgraded = AuthStore(tmp_path / "old-data")
    with upgraded._connect() as db:
        before = tuple(
            db.execute(
                "SELECT username,salt,password_hash,role,scopes,active FROM users"
            ).fetchone()
        )
    token = upgraded.login("LegacyAdmin", LEGACY_PASS, "127.0.0.1")
    assert upgraded.principal(token).username == "LegacyAdmin"
    with upgraded._connect() as db:
        after = tuple(
            db.execute(
                "SELECT username,salt,password_hash,role,scopes,active FROM users"
            ).fetchone()
        )
    assert before == after == LEGACY_ROW


def test_username_paste_spaces_are_tolerated_but_password_not_modified(tmp_path):
    store = legacy_store(tmp_path / "data")
    app = FastAPI()
    app.state.container = SimpleNamespace(
        settings=SimpleNamespace(business_profile="jiahui", jiahui_data_dir=str(store.directory))
    )
    app.include_router(router, prefix="/api/v1")
    with TestClient(app) as client:
        response = client.post(
            "/api/v1/auth/login", json={"username": " LegacyAdmin ", "password": LEGACY_PASS}
        )
        assert response.status_code == 200 and response.json()["username"] == "LegacyAdmin"
    store.create_user("spaces", "  valid test password  ", "sales")
    assert (
        store.principal(store.login("spaces", "  valid test password  ", "local")).username
        == "spaces"
    )
    with pytest.raises(HTTPException):
        store.login("spaces", "valid test password", "local")


def test_same_relative_setting_is_stable_across_upgrade_install_folders(tmp_path, monkeypatch):
    home = tmp_path / "stable-home"
    home.mkdir()
    (home / "desktop.json").write_text(json.dumps({"data_dir": "data"}), encoding="utf-8")
    for name in ["old-install", "new-install"]:
        folder = tmp_path / name
        folder.mkdir()
        monkeypatch.chdir(folder)
        assert data_directory(home) == (home / "data").resolve()


def test_operator_can_reselect_original_accounts_without_copying_or_resetting(tmp_path):
    home = tmp_path / "home"
    home.mkdir()
    (home / "desktop.json").write_text(
        json.dumps({"data_dir": "wrong-data", "other_setting": "keep"}), encoding="utf-8"
    )
    original = legacy_store(tmp_path / "existing-data")
    before = original.path.read_bytes()
    accounts = inspect_accounts(original.directory)
    assert set(accounts[0]) == {"username", "role", "active"}
    select_existing_data(home, original.directory)
    assert data_directory(home) == original.directory.resolve()
    assert original.path.read_bytes() == before
    assert (
        json.loads((home / "desktop.json").read_text(encoding="utf-8"))["other_setting"] == "keep"
    )
    assert list((home / "backups").glob("desktop-*.json"))
    assert (
        AuthStore(data_directory(home))
        .principal(AuthStore(data_directory(home)).login("LegacyAdmin", LEGACY_PASS, "local"))
        .username
        == "LegacyAdmin"
    )


def test_offline_reset_preserves_business_files_and_scopes_revokes_sessions(tmp_path):
    store = legacy_store(tmp_path / "data")
    business = store.directory / "products.json"
    business.write_text('{"do_not_change":"业务资料"}', encoding="utf-8")
    before = business.read_bytes()
    token = store.login("LegacyAdmin", LEGACY_PASS, "127.0.0.1")
    otherpass = secrets.token_urlsafe(24)
    store.create_user("other", otherpass, "sales")
    other = store.login("other", otherpass, "127.0.0.1")
    newpass = secrets.token_urlsafe(24)
    store.reset_password("LegacyAdmin", newpass)
    assert business.read_bytes() == before
    with pytest.raises(HTTPException):
        store.principal(token)
    assert store.principal(other).username == "other"
    with pytest.raises(HTTPException):
        store.login("LegacyAdmin", LEGACY_PASS, "127.0.0.1")
    principal = store.principal(store.login("LegacyAdmin", newpass, "127.0.0.1"))
    assert principal.role == "admin" and principal.scopes == frozenset(LEGACY_ROW[4].split(","))
    assert list((store.directory / "backups").glob("auth-*.sqlite3"))


def test_reset_cannot_create_users_enable_disabled_or_accept_weak_password(tmp_path):
    store = legacy_store(tmp_path / "data")
    with pytest.raises(ValueError, match="账号不存在"):
        store.reset_password("unknown", secrets.token_urlsafe(24))
    with pytest.raises(ValueError, match="至少12位"):
        store.reset_password("LegacyAdmin", "short")
    store.set_access("LegacyAdmin", "admin", frozenset({"products"}), False)
    with pytest.raises(ValueError, match="已停用"):
        store.reset_password("LegacyAdmin", secrets.token_urlsafe(24))


def test_readonly_inspection_does_not_initialize_missing_database(tmp_path):
    with pytest.raises(ValueError, match="没有 auth.sqlite3"):
        inspect_accounts(tmp_path)
    assert not (tmp_path / "auth.sqlite3").exists()
